 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Hello! Thanks for contacting Nimbus Telecom. I'm Sana. How can I help you today?",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "hi, i have a problem with my bill. i was charged twice for the same service last month and its really annoying",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I need your account number to access the details.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "it is 41433295. my name is Vivek Brown",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "Thank you. Please provide your phone number and email for the record.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "phone is 92859 63349 and email is vivek.68@examplemail.com",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I see the duplicate charge of $15.00 on your statement.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "yeah, so can you just fix it now? i dont want to pay for something i didnt use",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I will raise a refund request for the wrong charge now.",
      "tags": [
        "action:refund_request"
      ]
    },
    {
      "speaker": "customer",
      "text": "great, so i'll get my money back today?",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "The refund is subject to approval and will take 7-10 business days to process.",
      "tags": [
        "disclosure"
      ]
    },
    {
      "speaker": "customer",
      "text": "what?? 10 days?? this is ridiculous. you guys messed up and now i have to wait weeks for my own money 😡",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "That is the standard procedure.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "this is terrible service. i am so frustrated with how you're handling this!!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Is there anything else I can help you with? I have submitted the request and you will be notified via email. Goodbye.",
      "tags": [
        "closure"
      ]
    }
  ]
}
